from typing import Iterable, List, Mapping, Tuple, Set, Dict
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location
from stockflow.on_hand_by_location import on_hand_by_location


def cycle_count_variance(
    lines: Iterable[str], 
    case_sizes: Mapping[str, int], 
    counts: Mapping[Tuple[str, str], int]
) -> List[Tuple[str, str, int]]:
    """
    Compare a cycle count with system stock and report the differences.
    """
    system_stock = on_hand_by_location(lines, case_sizes)

    sys_by_loc: Dict[str, Dict[str, int]] = {}
    for (sku, loc), qty in system_stock.items():
        sys_by_loc.setdefault(loc, {})[sku] = qty

    norm_counts: Dict[Tuple[str, str], int] = {}
    counted_locs: Set[str] = set()

    for (raw_sku, raw_loc), qty in counts.items():
        if qty < 0:
            raise ValueError(f"Counted quantity cannot be negative: {qty}")

        sku = normalize_sku(raw_sku)
        lt = parse_location(raw_loc)
        loc = f"{lt[0]}-{lt[1]:02d}-{lt[2]:02d}-{lt[3]}"

        norm_counts[(sku, loc)] = norm_counts.get((sku, loc), 0) + qty
        counted_locs.add(loc)

    results = []
    for loc in counted_locs:
        sys_skus = sys_by_loc.get(loc, {})
        # SKUs that were counted in this location
        cnt_skus = {sku for (sku, l) in norm_counts if l == loc}

        all_skus = set(sys_skus.keys()) | cnt_skus
        for sku in all_skus:
            c_qty = norm_counts.get((sku, loc), 0)
            s_qty = sys_skus.get(sku, 0)
            variance = c_qty - s_qty
            if variance != 0:
                results.append((sku, loc, variance))

    return sorted(results, key=lambda x: (x[1], x[0]))"
    }
  },
  "messages": []
}
